 for name in paths:
  expected=subprocess.check_output(['git','show',baseline+':'+name]); actual=pathlib.Path(name).read_bytes()
  record={'sha256':sha(actual),'baseline_byte_exact':actual==expected}
  if name.endswith('.py'):
   record.update(ast_sha256=ast_hash(actual),baseline_ast_exact=ast_hash(actual)==ast_hash(expected))
